import re
from fractions import Fraction

def fraction_expr(s: str) -> str:
    if not isinstance(s, str) or not s.strip():
        raise ValueError("empty input")

    token_re = re.compile(r'\d+/\d+|\d+|[()+\-*]')
    tokens = []
    i, n = 0, len(s)
    while i < n:
        if s[i] == ' ':
            i += 1
            continue
        m = token_re.match(s, i)
        if not m:
            raise ValueError(f"bad token at {i}")
        tokens.append(m.group(0))
        i = m.end()
    if not tokens:
        raise ValueError("no tokens")

    pos = 0
    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while peek() in ('+', '-'):
            op = tokens[pos]; pos += 1
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while peek() == '*':
            pos += 1
            val = val * parse_factor()
        return val

    def parse_factor():
        nonlocal pos
        neg = False
        while peek() in ('+', '-'):
            if tokens[pos] == '-':
                neg = not neg
            pos += 1
        val = parse_atom()
        return -val if neg else val

    def parse_atom():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end")
        if tok == '(':
            pos += 1
            val = parse_expr()
            if peek() != ')':
                raise ValueError("missing )")
            pos += 1
            return val
        if re.fullmatch(r'\d+/\d+', tok):
            num, den = tok.split('/')
            den_i = int(den)
            if den_i == 0:
                raise ValueError("zero denominator")
            pos += 1
            return Fraction(int(num), den_i)
        if re.fullmatch(r'\d+', tok):
            pos += 1
            return Fraction(int(tok))
        raise ValueError(f"bad atom {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("trailing tokens")

    if result == 0:
        return "0"
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"
